/bin/zsh -lc "node --input-type=module -e '
import { Readable, Writable } from '\\''node:stream'\\'';
import { pipeline } from '\\''node:stream/promises'\\'';
for (const scenario of ['\\''success'\\'', '\\''abort'\\'', '\\''sourceError'\\'', '\\''sinkError'\\'']) {
  const ctl = new AbortController();
  let releaseSource, releaseSink, failed = false;
  const source = new Readable({ objectMode:true, read() { if (failed) return; failed=true; this.push(1); if (scenario==='\\''success'\\'') this.push(null); }, destroy(err, cb) { releaseSource=()=>cb(err); } });
  const sink = new Writable({ objectMode:true, write(x,e,cb) { if (scenario==='\\''success'\\'') cb(); else setImmediate(()=> { if (scenario==='\\''abort'\\'') ctl.abort(); else if (scenario==='\\''sourceError'\\'') source.destroy(new Error('\\''source'\\'')); else cb(new Error('\\''sink'\\'')); }); }, destroy(err, cb) { releaseSink=()=>cb(err); } });
  let state='\\''pending'\\''; const task = pipeline(source,sink,{signal:ctl.signal}).then(()=>state='\\''fulfilled'\\'', e=>state=e.name+'\\'':'\\''+e.message);
  await new Promise(setImmediate); await new Promise(setImmediate);
  console.log(scenario, '\\''before cleanup'\\'', state, "'!!releaseSource, !!releaseSink, source.closed, sink.closed);
  releaseSink?.();
  await new Promise(setImmediate);
  console.log(scenario,'"'\\''after sink cleanup'\\'', state, "'!!releaseSource, !!releaseSink, source.closed,sink.closed);
  releaseSource?.();
  await new Promise(setImmediate);
  releaseSink?.(); await task;
  console.log(scenario, '"'\\''after all cleanup'\\'', state,source.closed,sink.closed);
}'"

/bin/zsh -lc "node --input-type=module -e '
import { Readable, Writable } from '\\''node:stream'\\'';
import { pipeline } from '\\''node:stream/promises'\\'';
const controller = new AbortController(); controller.abort();
let reads=0,writes=0;
const source = new Readable({objectMode:true,read(){reads++;this.push({});}});
const sink = new Writable({objectMode:true,write(r,e,c){writes++;c();}});
try { await pipeline(source,sink,{signal:controller.signal}); } catch(e) { console.log(e.name,reads,writes,source.closed,sink.closed); }
'"

