  .replace('\\''for (const [name, run] of cases)'\\'', \"for (const [name, run] of cases.filter(([name]) => name === '\\''success_waits_for_close_autoDestroy_false'\\''))\");
await import('\\''data:text/javascript;base64,'\\'' + Buffer.from(test).toString('\\''base64'\\''));
